package httpapi

import (
	"context"
	"strings"
	"sync"
	"time"

	"github.com/BryantVanOrden/AgentFleet/backend/internal/connectors"
	"github.com/BryantVanOrden/AgentFleet/backend/internal/vault"
	"github.com/BryantVanOrden/AgentFleet/backend/pkg/protocol"
)

// peerReplyKind marks a message generated by this responder.
//
// It is what stops two idle agents talking forever: a reply never triggers
// another reply. Agents can still start a thread themselves mid-task with
// message_peer, and a human can always say something new.
const peerReplyKind = "reply"

// RunPeerResponder lets idle agents answer messages addressed to them.
//
// The agent loop only reads its inbox while a task is running (peerContext is
// built per turn), so an instance sitting idle never saw a broadcast and never
// answered one — which reads, correctly, as "nobody responded". This closes
// that gap: an idle instance still belongs to the fleet and should reply when
// spoken to.
//
// Instances that are mid-task are skipped on purpose. They will see the message
// in their next turn's FLEET block with the full context of what they are
// doing, which is a better answer than one composed out of band.
func (s *Server) RunPeerResponder(ctx context.Context) {
	const interval = 15 * time.Second

	// Last message answered per instance, so a reply is generated once. Held
	// in memory deliberately: on restart every instance re-reads its recent
	// inbox, and answering a stale message twice is cheaper than tracking
	// acknowledgements in the database.
	var mu sync.Mutex
	seen := map[string]time.Time{}

	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			instances, err := s.db.ListInstances(ctx)
			if err != nil {
				continue
			}
			for i := range instances {
				inst := instances[i]
				if inst.State != protocol.InstanceRunning {
					continue
				}
				if s.instanceIsBusy(ctx, inst.ID) {
					continue
				}

				mu.Lock()
				since := seen[inst.ID]
				mu.Unlock()

				msg, ok := s.nextUnanswered(ctx, inst.ID, since)
				if !ok {
					continue
				}

				mu.Lock()
				seen[inst.ID] = msg.CreatedAt
				mu.Unlock()

				s.replyToPeer(ctx, inst, msg)
			}
		}
	}
}

// instanceIsBusy reports whether a task is mid-flight on this instance. A busy
// agent is left alone: it will read the message in its next turn, with the
// context of what it is actually doing.
func (s *Server) instanceIsBusy(ctx context.Context, instanceID string) bool {
	tasks, err := s.db.ListTasks(ctx, instanceID, 20)
	if err != nil {
		// Unknown means leave it alone, rather than risk talking over a run.
		return true
	}
	for _, t := range tasks {
		switch t.State {
		case protocol.TaskRunning, protocol.TaskQueued, protocol.TaskAwaitingHuman:
			return true
		}
	}
	return false
}

// nextUnanswered finds the newest message this instance should answer.
//
// Only one per tick: answering a backlog all at once would flood the thread,
// and the newest message is the one worth responding to.
func (s *Server) nextUnanswered(ctx context.Context, instanceID string, since time.Time) (protocol.PeerMessage, bool) {
	msgs := vault.GlobalBus.ListMessages(ctx, instanceID, 10)

	var best protocol.PeerMessage
	found := false
	for _, m := range msgs {
		switch {
		case m.FromInstanceID == instanceID: // never answer yourself
		case m.Kind == peerReplyKind: // replies do not beget replies
		case !m.CreatedAt.After(since):
		case found && !m.CreatedAt.After(best.CreatedAt):
		default:
			best, found = m, true
		}
	}
	return best, found
}

func (s *Server) replyToPeer(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	scope := "you directly"
	if msg.ToInstanceID == "broadcast" {
		scope = "the whole fleet"
	}

	// "What is everyone up to" is the question this feature exists to answer,
	// and it cannot be answered from the message alone. Give the agent its own
	// recent history so the reply is a real status report rather than a
	// paraphrase of the question.
	status := s.recentActivity(ctx, inst)

	resp, err := s.models.CompleteFor(ctx, inst.ProviderIDs, connectors.Request{
		System: "You are the agent \"" + inst.Name + "\" in a fleet of autonomous " +
			"desktop agents, reporting to your operator. " + scope +
			" was messaged.\n\n" + status + "\n\n" +
			"Reply in one or two short sentences, in the first person, as a status " +
			"update. Say what you have actually been doing and whether you are free. " +
			"Ground every claim in the history above: if it says you have run nothing, " +
			"say you are idle and available. Never invent work, never claim to have " +
			"started something, and do not offer a list of your capabilities unless " +
			"you were asked what you can do.",
		Messages: []connectors.Message{{
			Role: connectors.RoleUser,
			Text: msg.FromInstanceName + " asked: " + msg.Content,
		}},
		// A reasoning model would spend the whole budget thinking and return
		// nothing; this is small talk between agents, not a plan.
		DisableThinking: true,
		MaxTokens:       220,
		Temperature:     0.3,
	})
	if err != nil {
		s.log.Warn("peer reply failed", "instance", inst.ID, "err", err)
		return
	}
	body := strings.TrimSpace(resp.Text)
	if body == "" {
		return
	}

	// Where the reply goes.
	//
	// An operator broadcast is answered in the group so every reply sits under
	// the question. Anything else — an agent asking another agent something —
	// is answered directly to the asker, which keeps agent chatter in its own
	// thread instead of filling the fleet channel with conversations the
	// operator did not start. The direct threads are still visible; they are
	// just not mixed in.
	to := msg.FromInstanceID
	if isOperator(msg) {
		// The operator has no instance ID for a reply to be addressed to. In a
		// two-agent thread the answer goes to the other agent, which is what
		// lets the pair carry on talking; anywhere else it goes to the fleet.
		if other, ok := vault.GlobalBus.OtherAgentMember(msg.ConversationID, inst.ID); ok {
			to = other
		} else {
			to = "broadcast"
		}
	}
	if to == "" {
		to = "broadcast"
	}

	// Which thread the answer belongs in is a separate question from who it is
	// addressed to, and conflating them leaked replies. An operator question in
	// a pair thread has no instance to address, so `to` falls back to
	// broadcast -- that must not drag the answer out of the thread it was
	// asked in and into the fleet channel.
	conv := msg.ConversationID
	if conv == "" {
		conv = protocol.BroadcastConversationID
	}
	vault.GlobalBus.SendMessageIn(ctx, conv, inst.ID, inst.Name, to, peerReplyKind, body, nil)
	s.log.Info("agent answered a peer message", "instance", inst.Name, "to", to, "conversation", conv)
}

// isOperator reports whether a message came from a human rather than an agent.
// Operator messages have no originating instance.
func isOperator(m protocol.PeerMessage) bool {
	return strings.TrimSpace(m.FromInstanceID) == ""
}

// recentActivity summarises what this agent has actually been doing, so a
// status reply is grounded in the record rather than improvised.
func (s *Server) recentActivity(ctx context.Context, inst protocol.Instance) string {
	tasks, err := s.db.ListTasks(ctx, inst.ID, 5)
	if err != nil || len(tasks) == 0 {
		return "YOUR HISTORY\nYou have not been given any work yet. You are idle and available."
	}

	var sb strings.Builder
	sb.WriteString("YOUR HISTORY (most recent first)\n")
	for i, t := range tasks {
		if i >= 3 {
			break
		}
		line := "- " + string(t.State) + ": " + trunc(t.Goal, 120)
		switch {
		case t.Result != "":
			line += " — outcome: " + trunc(t.Result, 160)
		case t.Error != "":
			line += " — failed: " + trunc(t.Error, 160)
		}
		sb.WriteString(line + "\n")
	}
	running := false
	for _, t := range tasks {
		if t.State == protocol.TaskRunning || t.State == protocol.TaskQueued {
			running = true
			break
		}
	}
	if running {
		sb.WriteString("Something of yours is still in flight.")
	} else {
		sb.WriteString("Nothing is running right now; you are free.")
	}
	return sb.String()
}

func trunc(s string, n int) string {
	s = strings.TrimSpace(s)
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}
